from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]
DISPATCHER = ROOT / 'tools' / 'mirror_sync' / 'universal_job_dispatcher.py'


def test_operational_complete_routes_to_done_not_rejected():
    text = DISPATCHER.read_text(encoding='utf-8')
    match = re.search(
        r'target = DONE / path\.name if result\[\"status\"\] in \{([^}]*)\} else REJECTED / path\.name',
        text,
    )
    assert match is not None, 'terminal lifecycle routing expression not found'
    terminal_done_states = {
        token.strip().strip('\"\'')
        for token in match.group(1).split(',')
        if token.strip()
    }
    assert 'OPERATIONAL_COMPLETE' in terminal_done_states
    assert 'READ_ONLY_COMPLETE' in terminal_done_states
    assert 'INTEGRATED' in terminal_done_states
